<section class="page-hero"><div class="container"><p class="section-label">Our People</p><h1>Our Advocates</h1></div></section><section class="page-section"><div class="container card-grid card-grid--team"><?php foreach ($advocates as $advocate): ?><article class="advocate-card"><div class="advocate-card__image"><?php if (!empty($advocate['photo_path'])): ?><img src="<?= htmlspecialchars($advocate['photo_path'], ENT_QUOTES, 'UTF-8') ?>" alt="<?= htmlspecialchars($advocate['first_name'].' '.$advocate['last_name'], ENT_QUOTES, 'UTF-8') ?>"><?php else: ?><div class="advocate-card__placeholder"><?= htmlspecialchars(strtoupper(substr($advocate['first_name'],0,1).substr($advocate['last_name'],0,1)), ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?></div><div class="advocate-card__content"><p class="section-label"><?= htmlspecialchars($advocate['title'] ?? '', ENT_QUOTES, 'UTF-8') ?></p><h3><?= htmlspecialchars($advocate['first_name'].' '.$advocate['last_name'], ENT_QUOTES, 'UTF-8') ?></h3><p><?= htmlspecialchars($advocate['bio'] ?? '', ENT_QUOTES, 'UTF-8') ?></p><a href="/advocates/<?= rawurlencode($advocate['slug']) ?>">View profile →</a></div></article><?php endforeach; ?></div></section>